def to_xml(self, value: Any, version: str, nsmap: Dict[str, str]={},
    prettyprint: bool=True, indent: str='') ->str:
    from . import gpx as mod_gpx
    if version not in ('1.0', '1.1'):
        raise mod_gpx.GPXException(f'Invalid version: {version}')

    # Handle the case where value might be a GPX object itself
    if hasattr(self, 'gpx_10_fields') and hasattr(self, 'gpx_11_fields'):
        # This is a GPX object, use the standard conversion
        # The method should be called on the object itself, not pass 'self' as value
        return gpx_fields_to_xml(self, 'gpx', version, nsmap=nsmap, 
                                prettyprint=prettyprint, indent=indent)
    else:
        # This is probably a field value being converted
        # For now, just return the value as string
        return str(value)
